/// <reference path="../deno.d.ts" />
// ============================================================
// paymongo-return — Post-checkout redirect back to the resident app
// ------------------------------------------------------------
// PayMongo success/cancel URLs point here (HTTPS). We immediately
// redirect to the app deep link so Expo openAuthSessionAsync can
// dismiss the browser. Confirmation still comes from
// paymongo-webhook / verify-paymongo-payment — never from this redirect.
// ============================================================

const APP_SUCCESS = "residents://payment-success";
const APP_CANCEL = "residents://payment-cancelled";

function htmlPage(ok: boolean, appUrl: string): string {
  const title = ok ? "Payment submitted" : "Checkout closed";
  const message = ok
    ? "You can close this page and return to the BKWB app. Your bill updates to Paid after PayMongo confirms the payment."
    : "Checkout was closed. Return to the BKWB app to continue.";
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${title} - BKWB</title>
  <style>
    body { font-family: system-ui, -apple-system, Segoe UI, sans-serif; margin: 0; min-height: 100vh; display: grid; place-items: center; background: #f8fafc; color: #0f172a; }
    .card { max-width: 26rem; margin: 1.5rem; padding: 1.75rem; background: #fff; border: 1px solid #e2e8f0; border-radius: 1rem; text-align: center; }
    h1 { font-size: 1.25rem; margin: 0 0 0.75rem; color: #047857; }
    p { margin: 0 0 1.25rem; line-height: 1.5; color: #475569; font-size: 0.95rem; }
    a { display: inline-block; padding: 0.75rem 1.25rem; background: #047857; color: #fff; text-decoration: none; border-radius: 0.5rem; font-weight: 600; }
  </style>
</head>
<body>
  <main class="card">
    <h1>${title}</h1>
    <p>${message}</p>
    <a href="${appUrl}">Open BKWB app</a>
  </main>
  <script>
    // Best-effort deep link for standalone builds. Expo Go AuthSession
    // already dismisses when this HTTPS page loads — no redirect required.
    try { window.location.replace(${JSON.stringify(appUrl)}); } catch (e) {}
  </script>
</body>
</html>`;
}

Deno.serve((req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, OPTIONS",
        "Access-Control-Allow-Headers": "*",
      },
    });
  }

  const url = new URL(req.url);
  const status = (url.searchParams.get("status") || "success").toLowerCase();
  const ok = status !== "cancel" && status !== "cancelled";
  const billId = (url.searchParams.get("bill_id") || "").trim();
  const appUrl = `${ok ? APP_SUCCESS : APP_CANCEL}${billId ? `?bill_id=${encodeURIComponent(billId)}` : ""}`;

  // Always serve HTML so openAuthSessionAsync can complete on this HTTPS URL
  // (Expo Go). Deep-link attempt is secondary for installed builds.
  return new Response(htmlPage(ok, appUrl), {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "no-store",
      "Access-Control-Allow-Origin": "*",
    },
  });
});
